"""Tests for scripts/build_legal_dict.py (LexPredict CSV + Open Legal Dictionary JSON)."""

from pathlib import Path

from scripts.build_legal_dict import (
    _collect_words_from_lexpredict_csv,
    _collect_words_from_old_json,
    _collect_words_from_wikipedia_latin_legal,
    build_legal_set,
)

FIXTURES_DIR = Path(__file__).resolve().parent / "fixtures"
WIKIPEDIA_LATIN_FIXTURE = FIXTURES_DIR / "wikipedia_latin_legal.html"


def test_build_legal_dict_reads_lexpredict_csv() -> None:
    """Build script (or helper) extracts normalized words from LexPredict CSV. Edited by Cursor."""
    path = FIXTURES_DIR / "lexpredict_sample.csv"
    words = _collect_words_from_lexpredict_csv(path)
    assert "affirmance" in words
    assert "vacatur" in words
    assert "supreme" in words or "court" in words


def test_build_legal_dict_reads_old_json() -> None:
    """Build script extracts words from Open Legal Dictionary JSON (title field). Edited by Cursor."""
    path = FIXTURES_DIR / "old_sample.json"
    words = _collect_words_from_old_json(path)
    assert "affirmance" in words
    assert "vacatur" in words
    assert "habeas" in words
    assert "corpus" in words


def test_build_legal_dict_output_deduplicated_lowercase() -> None:
    """Output from build_legal_set is deduplicated and lowercase. Edited by Cursor."""
    paths_lex = [FIXTURES_DIR / "lexpredict_sample.csv"]
    paths_old = [FIXTURES_DIR / "old_sample.json"]
    result = build_legal_set(lexpredict_paths=paths_lex, old_json_paths=paths_old)
    assert result == frozenset(result)
    for w in result:
        assert w == w.lower(), f"expected lowercase: {w!r}"
    assert "affirmance" in result
    assert "Affirmance" not in result


def test_collect_words_from_wikipedia_latin_legal() -> None:
    """Wikipedia Latin legal terms HTML is parsed; tokenized words returned. Edited by Cursor."""
    html = WIKIPEDIA_LATIN_FIXTURE.read_text(encoding="utf-8")
    words = _collect_words_from_wikipedia_latin_legal(html)
    expected = {
        "amici",
        "patriae",
        "expression",
        "habeas",
        "corpus",
        "amicus",
        "curiae",
        "indicium",
    }
    for w in expected:
        assert w in words, f"expected {w!r} from Wikipedia fixture"
    assert "" not in words
    for w in words:
        assert w == w.lower(), f"expected lowercase: {w!r}"
        assert w.isalpha() or (all(c.isalpha() or c == "'" for c in w)), (
            f"no markup: {w!r}"
        )


def test_build_legal_set_includes_wikipedia_latin_legal() -> None:
    """build_legal_set merges Wikipedia Latin legal words when path given. Edited by Cursor."""
    result = build_legal_set(
        wikipedia_latin_legal_html_path=WIKIPEDIA_LATIN_FIXTURE,
    )
    expected = {
        "amici",
        "patriae",
        "expression",
        "habeas",
        "corpus",
        "amicus",
        "curiae",
        "indicium",
    }
    for w in expected:
        assert w in result, f"expected {w!r} in build_legal_set result"
    assert result == frozenset(result)
    for w in result:
        assert w == w.lower(), f"expected lowercase: {w!r}"
